edits.newText:
// B-015: show the jump glyph when the playing track is not
// currently visible in the browser list. This includes cases
// where its parent folder is already the browsed folder.
final browserVisible =
    browserPresentation.value != BrowserPresentation.swipeUp ||
    browserExpanded.value;
final shouldJump = playingPath != null &&
    playingPath.isNotEmpty &&
    (p.dirname(playingPath) != (path ?? '') ||
        !browserVisible ||
        !browserController.isTrackVisible(playingPath));
final showJumpGlyph = resolveJumpGlyphVisible(shouldJump);

